// === Tab: mySketch ===
let isMobile = /iPhone|iPod|Android/i.test(navigator.userAgent);

let img;
let pg;
let points = [];

const particles = 8000;
let radius_;

let repel_radius;
const attraction = 0.03;
const damping = 0.88;

const repel_strength = 2.2;

// dot styling
const BASE_SW = 0.7;     // smaller dots
const HIT_SW = 1.25;     // dots on the svg become slightly bigger
const BASE_A = 70;       // alpha for "ocean"/empty
const HIT_A = 255;       // alpha for svg areas

// sampling
const THRESH = 18;       // what counts as "ink"
const SAMPLE_STEP = 1;

let camZ;

function preload() {
  img = loadImage("https://openprocessing.org/sketch/2847889/files/earth.svg"); // ensure it is in Assets
}

function setup() {
  if (isMobile) {
    createCanvas(360, 360, WEBGL);
    radius_ = 140;
    repel_radius = 60;
  } else {
    createCanvas(900, 700, WEBGL);
    radius_ = 230;
    repel_radius = 90;
  }

  pixelDensity(1);

  // approximate default camera Z for p5 WEBGL
  camZ = (height / 2) / tan(PI / 6);

  // build a texture-sampling buffer
  const W = 900;
  const H = 450;
  pg = createGraphics(W, H);
  pg.pixelDensity(1);
  pg.clear();
  pg.background(0, 0);     // transparent-ish
  pg.image(img, 0, 0, W, H);
  pg.loadPixels();

  // create particles everywhere on a FULL sphere
  points = [];
  for (let i = 0; i < particles; i++) {
    let uv = randomUVUniformSphere();   // u,v in [0..1]
    let p3 = sphereFromUV(uv.u, uv.v, radius_);

    points.push({
      pos: p3.copy(),
      vel: createVector(0, 0, 0),
      home: p3.copy(),
      u: uv.u,
      v: uv.v,
    });
  }
}

function draw() {
  background(0);

  // rotate only by dragging
  orbitControl();

  // mouse in world on Z=0 plane
  let mouseWorld = mouseToWorldOnZPlane(0);

  beginShape(POINTS);

  for (let p of points) {
    // spring to home
    let toHome = p5.Vector.sub(p.home, p.pos).mult(attraction);
    p.vel.add(toHome);

    // 3D repulsion around mouseWorld
    let away = p5.Vector.sub(p.pos, mouseWorld);
    let d = away.mag();

    if (d > 0.0001 && d < repel_radius) {
      let falloff = 1 - d / repel_radius;
      away.normalize();

      // push
      away.mult(repel_strength * 10 * falloff);

      // BONUS: tiny swirl for nicer motion
      let swirl = createVector(-away.y, away.x, away.z).mult(0.55 * falloff);

      p.vel.add(away.add(swirl));
    }

    p.vel.mult(damping);
    p.pos.add(p.vel);

    // sample the svg using stored u,v (texture coords)
    let ink = sampleInk(p.u, p.v);

    // style per-point (bigger/stronger where svg exists)
    if (ink) {
      stroke(255, HIT_A);
      strokeWeight(HIT_SW);
    } else {
      stroke(255, BASE_A);
      strokeWeight(BASE_SW);
    }

    vertex(p.pos.x, p.pos.y, p.pos.z);
  }

  endShape();
}

// --- mouse ray to plane z=targetZ ---
function mouseToWorldOnZPlane(targetZ = 0) {
  let mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
  let my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;

  let camPos = createVector(0, 0, camZ);
  let rayDir = createVector(mx, my, -camZ).normalize();

  let t = (targetZ - camPos.z) / rayDir.z;
  return p5.Vector.add(camPos, p5.Vector.mult(rayDir, t));
}

// --- create uniform random UV on sphere (no pole clustering) ---
function randomUVUniformSphere() {
  // u: longitude 0..1
  // v: latitude 0..1
  let u = random();
  let y = random(-1, 1);         // uniform on sphere
  let v = acos(y) / PI;          // 0..1
  return { u, v };
}

// --- map UV to 3D point on sphere ---
function sphereFromUV(u, v, r) {
  let lon = map(u, 0, 1, -PI, PI);
  let lat = map(v, 0, 1, PI / 2, -PI / 2);

  let x = r * cos(lat) * cos(lon);
  var y = r * sin(lat);
  let z = r * cos(lat) * sin(lon);
  return createVector(x, y, z);
}

// --- sample "ink" from the svg buffer at UV ---
function sampleInk(u, v) {
  var x = constrain(floor(u * (pg.width - 1)), 0, pg.width - 1);
  var y = constrain(floor(v * (pg.height - 1)), 0, pg.height - 1);

  let idx = 4 * (y * pg.width + x);
  let r = pg.pixels[idx];
  let g = pg.pixels[idx + 1];
  let b = pg.pixels[idx + 2];
  let a = pg.pixels[idx + 3];

  // if svg has transparent bg, alpha helps.
  // if svg is dark on transparent, brightness helps.
  let br = (r + g + b) / 3;

  return (a > 10 && br > THRESH) || (br > THRESH && a > 0);
}

